{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "PRE-084, a morpholine-containing compound, reached 773.6 ng/g brain at Tmax in mice, demonstrating rapid and meaningful CNS distribution; high transfer supports the query's morpholine-containing scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "LM11A-31, which contains a morpholine and amide, crossed the blood-brain barrier with brain-to-plasma ratios exceeding 1 after oral dosing in mice, directly showing adequate CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "A pyridine/piperazine amide H3 receptor antagonist crossed the BBB with a brain-to-plasma ratio of about 1:1 in rats, supporting CNS penetration for the query's pyridine and amine-containing core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Biarylamides with piperazine substituents traversed the BBB and displayed excellent drug levels in mouse brains after oral dosing, supporting the query's biaryl/amine CNS-permeable phenotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A related piperazine-containing radiotracer showed high brain uptake in a cat PET scan across cortex, thalamus, striatum, and cerebellum, providing direct in vivo evidence of BBB penetration for this compound class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer in vivo CNS penetration measurements in rodents and cat, including morpholine- and pyridine/piperazine-containing analogues, consistently show meaningful BBB access; the query shares these CNS-permeable scaffolds, so pass is predicted.",
  "evidence_gaps": [
    "No direct brain/plasma PK or CSF measurement for the query molecule itself.",
    "No transporter (P-gp/BCRP) efflux data for the query.",
    "No human data; predictions rely on rodent and cat in vivo analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

